#!/usr/bin/env node
/**
 * Sync Hara design tokens from the single source of truth (uiux/design-language/hara) into this repository.
 * Zero dependencies. Tokens are generated files: never edit them by hand, run this script instead.
 *
 *   node scripts/sync-design-tokens.mjs [--from <uiux>/design-language/hara/dist]   copy + update DESIGN.md
 *   node scripts/sync-design-tokens.mjs --check                                     verify only (also used by the test)
 *
 * Source directory: --from, else $HARA_DESIGN_DIST, else ~/work/projects/ai/uiux/design-language/hara/dist.
 * DESIGN.md keeps a machine-readable block between the hara-design-sync markers: version, sourceSha, uiux commit,
 * and the sha256 of every generated file. --check fails when a generated file was edited or the block is out of date.
 */
import { createHash } from 'node:crypto'
import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import { homedir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

/** [file in uiux dist/, path in this repo] */
export const FILES = [["hara-tokens.cli.ts", "src/tui/hara-tokens.generated.ts"]]

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const DESIGN = join(ROOT, 'DESIGN.md')
const START = '<!-- hara-design-sync:start (generated by scripts/sync-design-tokens.mjs — do not edit) -->'
const END = '<!-- hara-design-sync:end -->'
const sha256 = text => createHash('sha256').update(text).digest('hex')
const headerOf = text => {
  const m = text.match(/version (\d+\.\d+\.\d+) · sourceSha ([0-9a-f]{64})/) ?? text.match(/"version": "(\d+\.\d+\.\d+)",\s*"sourceSha": "([0-9a-f]{64})"/)
  return m ? { version: m[1], sourceSha: m[2] } : null
}

export function readBlock(designText = readFileSync(DESIGN, 'utf8')) {
  const i = designText.indexOf(START), j = designText.indexOf(END)
  if (i < 0 || j < i) return null
  const body = designText.slice(i + START.length, j)
  const field = k => body.match(new RegExp(`^- ${k}: \`([^\`]+)\``, 'm'))?.[1]
  const files = Object.fromEntries([...body.matchAll(/^\| `([^`]+)` \| `([0-9a-f]{64})` \|$/gm)].map(m => [m[1], m[2]]))
  return { version: field('version'), sourceSha: field('sourceSha'), commit: field('uiux commit'), files }
}

/** Returns a list of problems; empty means the repository is in sync with what DESIGN.md records. */
export function verify() {
  const problems = [], block = readBlock()
  if (!block) return ['DESIGN.md has no hara-design-sync block']
  for (const [, target] of FILES) {
    const p = join(ROOT, target)
    if (!existsSync(p)) { problems.push(`${target} is missing`); continue }
    const text = readFileSync(p, 'utf8'), head = headerOf(text)
    if (block.files[target] !== sha256(text)) problems.push(`${target} differs from the recorded sha256 (edited by hand? re-run the sync)`)
    if (!head || head.version !== block.version || head.sourceSha !== block.sourceSha) problems.push(`${target} header does not match DESIGN.md (${block.version})`)
  }
  for (const recorded of Object.keys(block.files)) if (!FILES.some(([, t]) => t === recorded)) problems.push(`DESIGN.md records unknown file ${recorded}`)
  return problems
}

function sync(from) {
  const meta = JSON.parse(readFileSync(join(from, 'hara-tokens.json'), 'utf8'))
  let commit = 'unknown'
  try { commit = execFileSync('git', ['-C', from, 'log', '-1', '--format=%h', '--', '.'], { encoding: 'utf8' }).trim() || 'unknown' } catch { /* not a git checkout */ }
  const rows = []
  for (const [src, target] of FILES) {
    const text = readFileSync(join(from, src), 'utf8'), head = headerOf(text)
    if (!head || head.sourceSha !== meta.sourceSha) throw new Error(`${src} in ${from} is not from the same build as hara-tokens.json`)
    mkdirSync(dirname(join(ROOT, target)), { recursive: true })
    writeFileSync(join(ROOT, target), text)
    rows.push(`| \`${target}\` | \`${sha256(text)}\` |`)
  }
  const block = `${START}\n- version: \`${meta.version}\`\n- sourceSha: \`${meta.sourceSha}\`\n- uiux commit: \`${commit}\`\n\n| file | sha256 |\n|---|---|\n${rows.join('\n')}\n${END}`
  const design = readFileSync(DESIGN, 'utf8'), i = design.indexOf(START), j = design.indexOf(END)
  if (i < 0 || j < i) throw new Error('DESIGN.md has no hara-design-sync markers')
  writeFileSync(DESIGN, design.slice(0, i) + block + design.slice(j + END.length))
  console.log(`synced Hara tokens ${meta.version} (${meta.sourceSha.slice(0, 12)}, uiux ${commit}) → ${FILES.map(([, t]) => t).join(', ')}`)
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--check')) {
    const problems = verify()
    if (problems.length) { console.error(problems.join('\n')); process.exit(1) }
    console.log(`Hara tokens in sync (${readBlock().version})`)
  } else {
    const k = process.argv.indexOf('--from')
    sync(k > 0 ? resolve(process.argv[k + 1]) : process.env.HARA_DESIGN_DIST ?? join(homedir(), 'work/projects/ai/uiux/design-language/hara/dist'))
  }
}
